// Authentic Minecraft Official Default Skin Textures (Steve & Alex)
// Encoded in Base64 Data URIs and supported with instant pixel decoding for browser and tests.

export const STEVE_SKIN_BASE64 = '';

export const ALEX_SKIN_BASE64 = '';

export const STEVE_SKIN_DATA_URI = `data:image/png;base64,${STEVE_SKIN_BASE64}`;
export const ALEX_SKIN_DATA_URI = `data:image/png;base64,${ALEX_SKIN_BASE64}`;

let cachedSteveImg: HTMLImageElement | null = null;
let cachedAlexImg: HTMLImageElement | null = null;

export function getSteveSkinImage(): HTMLImageElement | null {
  if (typeof Image === 'undefined') return null;
  if (!cachedSteveImg) {
    cachedSteveImg = new Image();
    cachedSteveImg.src = STEVE_SKIN_DATA_URI;
  }
  return cachedSteveImg;
}

export function getAlexSkinImage(): HTMLImageElement | null {
  if (typeof Image === 'undefined') return null;
  if (!cachedAlexImg) {
    cachedAlexImg = new Image();
    cachedAlexImg.src = ALEX_SKIN_DATA_URI;
  }
  return cachedAlexImg;
}

export function getDefaultSkinImage(type: 'steve' | 'alex'): HTMLImageElement | null {
  return type === 'steve' ? getSteveSkinImage() : getAlexSkinImage();
}

// Robust PNG RGBA decoder for Node.js / offline headless environments
function decodeBase64Png(base64: string): { width: number; height: number; data: Uint8ClampedArray } | null {
  try {
    if (typeof process === 'undefined' || !process.versions || !process.versions.node) {
      return null;
    }
    const zlib = require('zlib');
    const buf = Buffer.from(base64, 'base64');
    let offset = 8;
    const idatChunks: Buffer[] = [];
    let width = 64, height = 64;

    while (offset < buf.length) {
      const len = buf.readUInt32BE(offset);
      const type = buf.toString('ascii', offset + 4, offset + 8);
      const data = buf.slice(offset + 8, offset + 8 + len);
      offset += 12 + len;

      if (type === 'IHDR') {
        width = data.readUInt32BE(0);
        height = data.readUInt32BE(4);
      } else if (type === 'IDAT') {
        idatChunks.push(data);
      } else if (type === 'IEND') {
        break;
      }
    }

    const decomp = zlib.inflateSync(Buffer.concat(idatChunks));
    const rawData = new Uint8ClampedArray(width * height * 4);
    const stride = width * 4;
    let srcPos = 0;
    let dstPos = 0;
    const prevRow = new Uint8Array(stride);
    const curRow = new Uint8Array(stride);

    const paeth = (a: number, b: number, c: number) => {
      const pv = a + b - c;
      const pa = Math.abs(pv - a);
      const pb = Math.abs(pv - b);
      const pc = Math.abs(pv - c);
      return (pa <= pb && pa <= pc) ? a : (pb <= pc ? b : c);
    };

    for (let y = 0; y < height; y++) {
      const filter = decomp[srcPos++];
      for (let x = 0; x < stride; x++) {
        const b = decomp[srcPos++];
        const left = x >= 4 ? curRow[x - 4] : 0;
        const up = prevRow[x];
        const upLeft = x >= 4 ? prevRow[x - 4] : 0;
        let val = b;
        if (filter === 1) val = (b + left) & 0xff;
        else if (filter === 2) val = (b + up) & 0xff;
        else if (filter === 3) val = (b + Math.floor((left + up) / 2)) & 0xff;
        else if (filter === 4) val = (b + paeth(left, up, upLeft)) & 0xff;
        curRow[x] = val;
        rawData[dstPos++] = val;
      }
      prevRow.set(curRow);
    }
    return { width, height, data: rawData };
  } catch {
    return null;
  }
}

export function createSteveSkinCanvas(): HTMLCanvasElement {
  const cv = document.createElement('canvas');
  cv.width = 64;
  cv.height = 64;
  const ctx = cv.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;

  const decoded = decodeBase64Png(STEVE_SKIN_BASE64);
  if (decoded) {
    const imgData = ctx.createImageData ? ctx.createImageData(decoded.width, decoded.height) : new ImageData(decoded.width, decoded.height);
    imgData.data.set(decoded.data);
    ctx.putImageData(imgData, 0, 0);
    return cv;
  }

  const img = getSteveSkinImage();
  if (img && img.complete && img.naturalWidth) {
    ctx.drawImage(img, 0, 0);
  }
  return cv;
}

export function createAlexSkinCanvas(): HTMLCanvasElement {
  const cv = document.createElement('canvas');
  cv.width = 64;
  cv.height = 64;
  const ctx = cv.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;

  const decoded = decodeBase64Png(ALEX_SKIN_BASE64);
  if (decoded) {
    const imgData = ctx.createImageData ? ctx.createImageData(decoded.width, decoded.height) : new ImageData(decoded.width, decoded.height);
    imgData.data.set(decoded.data);
    ctx.putImageData(imgData, 0, 0);
    return cv;
  }

  const img = getAlexSkinImage();
  if (img && img.complete && img.naturalWidth) {
    ctx.drawImage(img, 0, 0);
  }
  return cv;
}

export function loadSkinCanvasAsync(
  src: string | HTMLImageElement | null,
  fallbackType: 'steve' | 'alex' = 'alex'
): Promise<HTMLCanvasElement> {
  return new Promise((resolve) => {
    const targetDataUri = !src
      ? fallbackType === 'steve'
        ? STEVE_SKIN_DATA_URI
        : ALEX_SKIN_DATA_URI
      : typeof src === 'string'
        ? src
        : null;

    if (src instanceof HTMLImageElement) {
      if (src.complete && src.naturalWidth > 0) {
        const cv = document.createElement('canvas');
        cv.width = src.naturalWidth;
        cv.height = src.naturalHeight;
        const ctx = cv.getContext('2d')!;
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(src, 0, 0);
        return resolve(cv);
      }
      src.onload = () => {
        const cv = document.createElement('canvas');
        cv.width = src.naturalWidth;
        cv.height = src.naturalHeight;
        const ctx = cv.getContext('2d')!;
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(src, 0, 0);
        resolve(cv);
      };
      return;
    }

    if (targetDataUri && typeof Image !== 'undefined') {
      const img = new Image();
      let finished = false;
      const done = () => {
        if (finished) return;
        finished = true;
        const cv = document.createElement('canvas');
        cv.width = img.naturalWidth || 64;
        cv.height = img.naturalHeight || 64;
        const ctx = cv.getContext('2d')!;
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(img, 0, 0);
        resolve(cv);
      };
      img.onload = done;
      img.src = targetDataUri;
      if (img.complete && img.naturalWidth > 0) {
        done();
      }
      return;
    }

    // Node fallback
    const cv = fallbackType === 'steve' ? createSteveSkinCanvas() : createAlexSkinCanvas();
    resolve(cv);
  });
}
